"use client";
/* eslint-disable @next/next/no-img-element -- administrator-provided institution logos use mixed official sources */

import { useCallback, useEffect, useState } from "react";
import Link from "next/link";
import {
  Activity, Bell, BookOpen, Building2, ChevronLeft, CircleDollarSign, ClipboardList, CreditCard,
  FileVideo, GraduationCap, Headphones, LayoutDashboard, LoaderCircle, LogOut, Menu, MessageSquareText,
  Paperclip, Plus, Receipt, RefreshCw, Search, Settings, ShieldCheck, Sparkles, Star, TicketPercent, Upload,
  UserCog, UsersRound, X,
} from "lucide-react";
import { BrandLogo } from "@/components/brand-logo";
import { ThemeToggle } from "@/components/theme-provider";

type Institution = { slug:string; name:string; nameEn:string; region:string; type:string; logo?:string; domain?:string; specialties:number; courses:number; featured?:boolean; status?:string; directorySourceUrl?:string; aliases?:string[]; verificationStatus?:string };
type Course = { slug:string; title:string; titleEn:string; code?:string; description:string; university:string; universitySlug:string; specialty:string; specialtySlug?:string; price:number; oldPrice?:number; lessons:number; access:string; featured?:boolean; color:string; icon:string; status?:string; coverTheme?:string; sourceUrl?:string; verifiedAt?:string };
type Specialty = { slug:string; name:string; description:string; status:string; sourceUrl?:string; verifiedAt?:string; verificationStatus?:string; faculty?:string|null; degree?:string|null };
type UserRow = { id:number; email:string; phone:string|null; fullName:string; role:string; universitySlug:string|null; specialty:string|null; status:string; profileCompletedAt:string|null; onboardingCompletedAt:string|null; lastLoginAt:string|null; createdAt:string };
type OrderRow = { id:number; orderNumber:string; customerEmail:string; customerName:string; courseSlug:string; total:number; currency:string; status:string; createdAt:string };
type RequestRow = { id:number; courseName:string; university:string; specialty:string; status:string; name:string; phone:string; attachmentsCount:number; createdAt:string };
type TicketRow = { id:number; ticketNumber:string; userEmail:string|null; category:string; priority:string; title:string; message:string; contactChannel?:string; status:string; createdAt:string; updatedAt:string; replies:Array<{id:number;body:string;authorEmail:string;authorRole?:string;internal:boolean;createdAt:string;files?:Array<{id:number;originalName:string;contentType:string;sizeBytes:number}>}> };
type ReviewRow = { id:number; userEmail:string; courseSlug:string; rating:number; body:string; status:string; createdAt:string };
type UnitRow = { id:number; courseSlug:string; title:string; position:number; status:string };
type LessonRow = { id:string; courseSlug:string; unitId:number; title:string; position:number; durationSeconds:number; freePreview:boolean; status:string; videoAssetId:number|null };
type VideoRow = { id:number; courseSlug:string; lessonId:string; status:string; sizeBytes:number; createdAt:string };
type AuditRow = { id:number; actorEmail:string; action:string; entityType:string; entityId:string|null; createdAt:string };
type SupervisorAssignment = { id:number; supervisorId:number; institutionSlug:string; specialty:string; active:boolean; createdAt:string };
type ConsoleData = {
  metrics:{students:number;activeStudents:number;institutions:number;publishedCourses:number;orders:number;paidOrders:number;revenue:number;openRequests:number;openTickets:number;pendingReviews:number};
  services:{assistant:boolean;payments:boolean;email:boolean;videoSigning:boolean}; institutions:Institution[]; courses:Course[]; specialties:Specialty[];
  specialtyLinks:Array<{id:number;institutionSlug:string;specialtySlug:string;status:string}>; users:UserRow[]; orders:OrderRow[]; requests:RequestRow[];
  tickets:TicketRow[]; reviews:ReviewRow[]; units:UnitRow[]; lessons:LessonRow[]; videos:VideoRow[];
  notifications:Array<{id:number;title:string;body:string;audience:string;userEmail:string|null;actionUrl?:string|null;actionLabel?:string|null;presentation?:string;pushEnabled?:boolean;startsAt?:string|null;expiresAt?:string|null;createdAt:string}>;
  supervisorAssignments:SupervisorAssignment[];
  coupons:Array<{id:number;code:string;type:string;value:number;courseSlug:string|null;usedCount:number;usageLimit:number|null;status:string}>;
  settings:Record<string,string>; audit:AuditRow[]; generatedAt:string;
};

type View = "overview"|"institutions"|"specialties"|"courses"|"content"|"students"|"orders"|"requests"|"support"|"reviews"|"notifications"|"coupons"|"staff"|"audit"|"settings";
type Dialog = { kind:"institution"; item?:Institution }|{ kind:"specialty"; item?:Specialty }|{ kind:"course"; item?:Course }|{ kind:"staff"; item?:UserRow }|{ kind:"access"; user:UserRow }|null;

const menuGroups = [
  { label:"التشغيل", items:[{id:"overview",label:"نظرة عامة",icon:LayoutDashboard},{id:"orders",label:"الطلبات والمدفوعات",icon:Receipt},{id:"requests",label:"طلبات المواد",icon:ClipboardList},{id:"support",label:"الدعم",icon:Headphones}] },
  { label:"الكتالوج", items:[{id:"institutions",label:"الجامعات والشعارات",icon:Building2},{id:"specialties",label:"التخصصات والربط",icon:GraduationCap},{id:"courses",label:"المواد والأسعار",icon:BookOpen},{id:"content",label:"الوحدات والدروس والفيديو",icon:FileVideo}] },
  { label:"المستخدمون", items:[{id:"students",label:"الطلاب والصلاحيات",icon:UsersRound},{id:"staff",label:"المشرفون والإدارة",icon:UserCog},{id:"reviews",label:"التقييمات",icon:Star},{id:"notifications",label:"الإشعارات",icon:Bell}] },
  { label:"النظام", items:[{id:"coupons",label:"الكوبونات",icon:TicketPercent},{id:"settings",label:"التواصل والإعدادات",icon:Settings},{id:"audit",label:"سجل النشاط",icon:Activity}] },
] as const;

const titles:Record<View,string> = Object.fromEntries(menuGroups.flatMap((group)=>group.items.map((item)=>[item.id,item.label]))) as Record<View,string>;
const statusLabel=(value:string)=>({published:"منشور",hidden:"مخفي",draft:"مسودة",active:"نشط",suspended:"موقوف",paid:"مدفوع",pending:"معلّق",initiated:"بدأ الدفع",failed:"فشل",refunded:"مسترد",new:"جديد",assigned:"مسند",reviewing:"مراجعة",planned:"مخطط",producing:"إنتاج",available:"متاح",declined:"متعذر",open:"مفتوح",waiting:"بانتظار الطالب",resolved:"محلول",closed:"مغلق",rejected:"مرفوض"} as Record<string,string>)[value]||value;

export function AdminDashboard({ adminName }: { adminName:string }) {
  const [active,setActive]=useState<View>("overview"); const [sidebar,setSidebar]=useState(true); const [query,setQuery]=useState("");
  const [data,setData]=useState<ConsoleData|null>(null); const [loading,setLoading]=useState(true); const [error,setError]=useState(""); const [toast,setToast]=useState(""); const [dialog,setDialog]=useState<Dialog>(null);
  const load=useCallback(async()=>{setLoading(true);setError("");try{const response=await fetch("/api/admin/console",{credentials:"same-origin"});const result=await response.json() as ConsoleData&{error?:string};if(!response.ok)throw new Error(result.error||"تعذر تحميل لوحة الإدارة");setData(result);}catch(caught){setError(caught instanceof Error?caught.message:"تعذر التحميل");}finally{setLoading(false);}},[]);
  useEffect(()=>{const timer=window.setTimeout(()=>void load(),0);return()=>window.clearTimeout(timer);},[load]);
  const mutate=async(payload:Record<string,unknown>,success="تم حفظ التغييرات"):Promise<boolean>=>{try{const response=await fetch("/api/admin/console",{method:"POST",credentials:"same-origin",headers:{"content-type":"application/json"},body:JSON.stringify(payload)});const result=await response.json() as {error?:string};if(!response.ok)throw new Error(result.error||"تعذر الحفظ");setToast(success);setTimeout(()=>setToast(""),2800);await load();return true;}catch(caught){const message=caught instanceof Error?caught.message:"تعذر تنفيذ العملية";setToast(`تعذر التنفيذ: ${message}`);setTimeout(()=>setToast(""),4200);await load();return false;}};
  const openAdd=()=>{if(active==="institutions")setDialog({kind:"institution"});else if(active==="specialties")setDialog({kind:"specialty"});else if(active==="courses")setDialog({kind:"course"});else if(active==="staff")setDialog({kind:"staff"});};
  const canAdd=["institutions","specialties","courses","staff"].includes(active);
  const logout=async()=>{await fetch("/api/auth/logout",{method:"POST",credentials:"same-origin"});window.location.assign("/");};
  const render=()=>{if(!data)return null;const props={data,query,mutate,setDialog};switch(active){case"overview":return <Overview data={data} go={setActive}/>;case"institutions":return <Institutions {...props}/>;case"specialties":return <Specialties {...props}/>;case"courses":return <Courses {...props}/>;case"content":return <Content data={data} mutate={mutate} refresh={load}/>;case"students":return <Users data={data} query={query} mutate={mutate} setDialog={setDialog} role="student"/>;case"staff":return <Staff data={data} query={query} mutate={mutate}/>;case"orders":return <Orders data={data} query={query}/>;case"requests":return <Requests data={data} query={query} mutate={mutate}/>;case"support":return <Support data={data} query={query} mutate={mutate}/>;case"reviews":return <Reviews data={data} query={query} mutate={mutate}/>;case"notifications":return <Notifications data={data} mutate={mutate}/>;case"coupons":return <Coupons data={data} mutate={mutate}/>;case"settings":return <PlatformSettings data={data} mutate={mutate}/>;case"audit":return <Audit data={data} query={query}/>;}};
  return <main className={`admin-app ${sidebar?"":"admin-sidebar-closed"}`}><aside className="admin-sidebar"><div className="admin-brand"><BrandLogo compact/><button onClick={()=>setSidebar(false)} aria-label="إغلاق القائمة"><X size={18}/></button></div><div className="admin-context"><div><ShieldCheck size={17}/></div><span><strong>إدارة مراس</strong><small>بيانات حية وصلاحيات خادم</small></span></div><nav>{menuGroups.map((group)=><section key={group.label}><span>{group.label}</span>{group.items.map((item)=>{const Icon=item.icon;return <button key={item.id} className={active===item.id?"active":""} onClick={()=>{setActive(item.id);setQuery("");}}><Icon size={17}/><b>{item.label}</b>{item.id==="requests"&&data?.metrics.openRequests?<i>{data.metrics.openRequests}</i>:item.id==="support"&&data?.metrics.openTickets?<i>{data.metrics.openTickets}</i>:item.id==="reviews"&&data?.metrics.pendingReviews?<i>{data.metrics.pendingReviews}</i>:null}</button>;})}</section>)}</nav><button className="admin-logout" onClick={logout}><LogOut size={16}/> تسجيل الخروج</button></aside><section className="admin-main"><header className="admin-header"><div><button className="admin-menu-button" onClick={()=>setSidebar(!sidebar)} aria-label="القائمة"><Menu size={19}/></button><label><Search size={17}/><input value={query} onChange={(event)=>setQuery(event.target.value)} placeholder="ابحث في القسم الحالي..."/></label></div><div><ThemeToggle compact/><button className="icon-button" onClick={()=>void load()} aria-label="تحديث"><RefreshCw size={18}/></button><span className="admin-divider"/><span className="admin-user"><span>{adminName[0]}</span><div><strong>{adminName}</strong><small>مدير المنصة</small></div></span></div></header><div className="admin-content"><div className="admin-page-title"><div><p>لوحة الإدارة <ChevronLeft size={12}/> {titles[active]}</p><h1>{titles[active]}</h1></div>{canAdd&&<button className="button button-primary" onClick={openAdd}><Plus size={16}/> إضافة جديد</button>}</div>{loading&&!data?<Loading/>:error?<ErrorState text={error} retry={load}/>:render()}</div></section>{dialog&&data&&<AdminDialog dialog={dialog} data={data} close={()=>setDialog(null)} mutate={mutate} refresh={load}/>} {toast&&<div className="admin-toast"><Sparkles size={16}/>{toast}</div>}</main>;
}

function Loading(){return <section className="admin-panel live-loading"><LoaderCircle className="spin"/><h2>جارٍ تحميل بيانات التشغيل</h2></section>}
function ErrorState({text,retry}:{text:string;retry:()=>Promise<void>}){return <section className="admin-panel live-loading"><ShieldCheck/><h2>{text}</h2><button className="button button-primary" onClick={()=>void retry()}>إعادة المحاولة</button></section>}
function Metric({icon:Icon,label,value,copy,color}:{icon:React.ElementType;label:string;value:string;copy:string;color:string}){return <article className="admin-metric"><i className={color}><Icon size={20}/></i><span><small>{label}</small><strong>{value}</strong><em>{copy}</em></span></article>}

function Overview({data,go}:{data:ConsoleData;go:(view:View)=>void}){const services=[{key:"payments",label:"Tap Payments",copy:"مفتاح الدفع"},{key:"assistant",label:"المساعد الذكي",copy:"محرك المعرفة والسياق"},{key:"videoSigning",label:"الفيديو الخاص",copy:"توقيع البث"},{key:"email",label:"استعادة الحساب",copy:"إرسال البريد"}] as const;return <><div className="admin-metrics"><Metric icon={CircleDollarSign} label="إجمالي الإيراد المؤكد" value={`${data.metrics.revenue.toLocaleString("ar-SA")} ر.س`} copy={`${data.metrics.paidOrders} طلب مدفوع`} color="blue"/><Metric icon={UsersRound} label="الطلاب" value={data.metrics.students.toLocaleString("ar-SA")} copy={`${data.metrics.activeStudents} حساب نشط`} color="violet"/><Metric icon={Building2} label="الجهات التعليمية" value={String(data.metrics.institutions)} copy="قابلة للتعديل والشعار" color="green"/><Metric icon={BookOpen} label="المواد" value={String(data.courses.length)} copy={`${data.metrics.publishedCourses} بمحتوى دروس`} color="orange"/></div><div className="admin-dashboard-grid"><section className="admin-panel live-queue"><div className="admin-panel-head"><div><h2>طابور العمل</h2><p>أرقام فعلية من قاعدة البيانات</p></div></div>{[{label:"طلبات مواد مفتوحة",value:data.metrics.openRequests,view:"requests" as View},{label:"تذاكر دعم مفتوحة",value:data.metrics.openTickets,view:"support" as View},{label:"تقييمات تنتظر المراجعة",value:data.metrics.pendingReviews,view:"reviews" as View},{label:"عمليات دفع غير مكتملة",value:data.orders.filter((row)=>!["paid","refunded"].includes(row.status)).length,view:"orders" as View}].map((item)=><button key={item.label} onClick={()=>go(item.view)}><span>{item.label}</span><strong>{item.value}</strong><ChevronLeft size={16}/></button>)}</section><section className="admin-panel live-services"><div className="admin-panel-head"><div><h2>جاهزية الخدمات</h2><p>لا تُعرض المفاتيح السرية</p></div></div>{services.map((service)=><div key={service.key}><i className={data.services[service.key]?"ok":"warn"}/><span><strong>{service.label}</strong><small>{data.services[service.key]?`${service.copy} مضبوط`: `${service.copy} يحتاج متغير بيئة`}</small></span><em>{data.services[service.key]?"جاهز":"إجراء مطلوب"}</em></div>)}</section></div><section className="admin-panel live-recent"><div className="admin-panel-head"><div><h2>آخر العمليات</h2><p>آخر تحديث {new Date(data.generatedAt).toLocaleString("ar-SA")}</p></div><button onClick={()=>go("orders")}>عرض الكل <ChevronLeft size={14}/></button></div><Table headers={["الطلب","الطالب","المادة","المبلغ","الحالة"]}>{data.orders.slice(0,8).map((row)=><div className="live-table-row" key={row.orderNumber}><b dir="ltr">{row.orderNumber}</b><span>{row.customerName}<small>{row.customerEmail}</small></span><span>{data.courses.find((course)=>course.slug===row.courseSlug)?.title||row.courseSlug}</span><strong>{row.total} {row.currency}</strong><em className={`status ${row.status==="paid"?"published":"draft"}`}>{statusLabel(row.status)}</em></div>)}</Table></section></>}

function Table({headers,children}:{headers:string[];children:React.ReactNode}){return <div className="live-table"><div className="live-table-row live-table-head">{headers.map((header)=><span key={header}>{header}</span>)}</div>{children}</div>}
function includesQuery(query:string,...values:Array<string|number|null|undefined>){const needle=query.trim().toLowerCase();return !needle||values.join(" ").toLowerCase().includes(needle)}
function institutionPayload(row: ConsoleData["institutions"][number], status: string, featured: boolean) { return { action: "saveInstitution", slug: row.slug, name: row.name, nameEn: row.nameEn, region: row.region, type: row.type, domain: row.domain || "", directorySourceUrl: row.directorySourceUrl || "", verificationStatus: row.verificationStatus || "official-directory", aliases: row.aliases || [], logoUrl: row.logo || "", status, featured }; }

function Institutions({data,query,mutate,setDialog}:{data:ConsoleData;query:string;mutate:(p:Record<string,unknown>,s?:string)=>Promise<boolean>;setDialog:(d:Dialog)=>void}){const rows=data.institutions.filter((row)=>includesQuery(query,row.name,row.nameEn,row.region,row.type));return <section className="admin-panel data-panel"><div className="live-panel-note"><ShieldCheck size={17}/><p>يمكن رفع PNG/JPG/WebP إلى التخزين الدائم أو استخدام رابط HTTPS رسمي. يعالج إطار الشعار الوضعين الفاتح والداكن.</p></div><Table headers={["الجهة","النوع","المنطقة","التخصصات","المواد","إجراءات"]}>{rows.map((row)=><div className="live-table-row" key={row.slug}><span className="live-entity"><i>{row.logo?<img src={row.logo} alt=""/>:row.name[0]}</i><b>{row.name}<small>{row.nameEn}{row.featured?" · مميزة":""}</small></b></span><span>{row.type}</span><span>{row.region}</span><span>{row.specialties}</span><span>{row.courses}</span><span className="live-actions"><button onClick={()=>setDialog({kind:"institution",item:row})}>تعديل</button><button onClick={()=>void mutate(institutionPayload(row,"hidden",Boolean(row.featured)),"تم إخفاء الجهة")}>إخفاء</button></span></div>)}</Table></section>}

function Specialties({data,query,setDialog}:{data:ConsoleData;query:string;mutate:(p:Record<string,unknown>,s?:string)=>Promise<boolean>;setDialog:(d:Dialog)=>void}){const rows=data.specialties.filter((row)=>includesQuery(query,row.name,row.slug));return <section className="admin-panel data-panel"><div className="live-panel-note"><GraduationCap size={17}/><p>تُربط التخصصات بجامعة محددة. عند عدم وجود ربط إداري تستخدم المنصة الدليل الأكاديمي الرسمي/الاحتياطي للجهة.</p></div><Table headers={["التخصص","المعرّف","الجهات المرتبطة","الحالة","الوصف","إجراء"]}>{rows.map((row)=><div className="live-table-row" key={row.slug}><strong>{row.name}</strong><span dir="ltr">{row.slug}</span><span>{data.specialtyLinks.filter((link)=>link.specialtySlug===row.slug&&link.status==="published").length}</span><em className={`status ${row.status==="published"?"published":"draft"}`}>{statusLabel(row.status)}</em><span>{row.description||"—"}</span><button onClick={()=>setDialog({kind:"specialty",item:row})}>تعديل</button></div>)}</Table></section>}

function Courses({data,query,setDialog}:{data:ConsoleData;query:string;mutate:(p:Record<string,unknown>,s?:string)=>Promise<boolean>;setDialog:(d:Dialog)=>void}){const rows=data.courses.filter((row)=>includesQuery(query,row.title,row.university,row.specialty,row.code));return <section className="admin-panel data-panel"><Table headers={["المادة","الجامعة والتخصص","السعر","الدروس","الوصول","إجراء"]}>{rows.map((row)=><div className="live-table-row" key={row.slug}><span className="live-entity"><i className={`bg-gradient-to-br ${row.color}`}>{row.icon}</i><b>{row.title}<small>{row.code||row.slug}</small></b></span><span>{row.university}<small>{row.specialty}</small></span><strong>{row.price} ر.س</strong><span>{row.lessons}</span><span>{row.access}</span><button onClick={()=>setDialog({kind:"course",item:row})}>تعديل/تحويل لإدارة حية</button></div>)}</Table></section>}

function Content({data,mutate,refresh}:{data:ConsoleData;mutate:(p:Record<string,unknown>,s?:string)=>Promise<boolean>;refresh:()=>Promise<void>}){const managedSlugs=new Set(data.units.map((row)=>row.courseSlug));const[firstCourse]=data.courses;const[selected,setSelected]=useState(firstCourse?.slug||"");const units=data.units.filter((row)=>row.courseSlug===selected);const lessons=data.lessons.filter((row)=>row.courseSlug===selected);const submitUnit=async(event:React.FormEvent<HTMLFormElement>)=>{event.preventDefault();const form=new FormData(event.currentTarget);const ok=await mutate({action:"saveUnit",courseSlug:selected,title:form.get("title"),position:units.length,status:"published"},"تمت إضافة الوحدة");if(ok)event.currentTarget.reset();};const submitLesson=async(event:React.FormEvent<HTMLFormElement>)=>{event.preventDefault();const form=new FormData(event.currentTarget);const ok=await mutate({action:"saveLesson",id:form.get("id"),courseSlug:selected,unitId:Number(form.get("unitId")),title:form.get("title"),durationSeconds:Number(form.get("durationSeconds")),freePreview:form.get("freePreview")==="on",position:lessons.length,status:"published"},"تمت إضافة الدرس");if(ok)event.currentTarget.reset();};return <div className="live-content-grid"><section className="admin-panel"><div className="admin-panel-head"><div><h2>المادة</h2><p>اختر مادة أُنشئت أو حُوّلت إلى إدارة الكتالوج</p></div></div><select className="live-wide-select" value={selected} onChange={(event)=>setSelected(event.target.value)}>{data.courses.map((course)=><option value={course.slug} key={course.slug}>{course.title} — {course.university}</option>)}</select>{!managedSlugs.has(selected)&&<p className="live-hint">أضف المادة/احفظها من قسم المواد أولًا، ثم أنشئ وحدتها الأولى هنا.</p>}<form className="live-inline-form" onSubmit={submitUnit}><input name="title" required placeholder="اسم وحدة جديدة"/><button className="button button-primary"><Plus size={15}/> إضافة وحدة</button></form><div className="live-units">{units.map((unit)=><article key={unit.id}><header><span><strong>{unit.title}</strong><small>الوحدة #{unit.id}</small></span><em>{lessons.filter((lesson)=>lesson.unitId===unit.id).length} دروس</em></header>{lessons.filter((lesson)=>lesson.unitId===unit.id).map((lesson)=><div key={lesson.id}><span><b>{lesson.title}</b><small>{Math.round(lesson.durationSeconds/60)} دقيقة {lesson.freePreview?"· معاينة مجانية":""}</small></span><em>{data.videos.some((video)=>video.lessonId===lesson.id&&video.status==="ready")?"الفيديو جاهز":"بانتظار الفيديو"}</em></div>)}</article>)}</div></section><aside className="admin-panel live-builder-side"><h2>إضافة درس</h2><form onSubmit={submitLesson}><label>الوحدة<select name="unitId" required><option value="">اختر</option>{units.map((unit)=><option key={unit.id} value={unit.id}>{unit.title}</option>)}</select></label><label>معرّف الدرس<input name="id" required pattern="[A-Za-z0-9._-]{2,100}" placeholder="course-lesson-01" dir="ltr"/></label><label>العنوان<input name="title" required/></label><label>المدة بالثواني<input name="durationSeconds" required type="number" min="0"/></label><label className="live-check"><input name="freePreview" type="checkbox"/> درس تجريبي مجاني</label><button className="button button-primary">حفظ الدرس</button></form><h2>رفع فيديو خاص</h2><VideoUpload lessons={lessons} courseSlug={selected} reload={refresh}/></aside></div>}

function VideoUpload({lessons,courseSlug,reload}:{lessons:LessonRow[];courseSlug:string;reload:()=>Promise<void>}){const[message,setMessage]=useState("");const[busy,setBusy]=useState(false);const submit=async(event:React.FormEvent<HTMLFormElement>)=>{event.preventDefault();setBusy(true);setMessage("");const form=new FormData(event.currentTarget);form.set("courseSlug",courseSlug);try{const response=await fetch("/api/admin/videos",{method:"POST",credentials:"same-origin",body:form});const result=await response.json() as {error?:string};setMessage(response.ok?"تم رفع الفيديو إلى التخزين الخاص":result.error||"تعذر الرفع");if(response.ok){event.currentTarget.reset();await reload();}}catch{setMessage("تعذر الاتصال بالخادم أثناء الرفع");}finally{setBusy(false);}};return <form onSubmit={submit}><label>الدرس<select name="lessonId" required><option value="">اختر</option>{lessons.map((lesson)=><option value={lesson.id} key={lesson.id}>{lesson.title}</option>)}</select></label><label className="live-file"><Upload size={18}/><span>اختر ملف الفيديو (حتى 200MB)</span><input name="file" type="file" accept="video/*" required/></label><button className="button button-soft" disabled={busy}>{busy?"جارٍ الرفع...":"رفع إلى المخزن الخاص"}</button>{message&&<p className="live-hint">{message}</p>}</form>}

function Users({data,query,mutate,setDialog,role}:{data:ConsoleData;query:string;mutate:(p:Record<string,unknown>,s?:string)=>Promise<boolean>;setDialog:(d:Dialog)=>void;role:"student"|"staff"}){const rows=data.users.filter((row)=>role==="student"?row.role==="student":row.role!=="student").filter((row)=>includesQuery(query,row.fullName,row.email,row.phone,row.specialty));return <section className="admin-panel data-panel"><Table headers={["المستخدم","الدور","الجامعة والتخصص","اكتمال الملف","الحالة","إجراءات"]}>{rows.map((row)=><div className="live-table-row" key={row.id}><span className="live-entity"><i>{row.fullName[0]}</i><b>{row.fullName}<small>{row.email} · {row.phone||"بدون جوال"}</small></b></span><select defaultValue={row.role} onChange={(event)=>void mutate({action:"updateUser",id:row.id,status:row.status,role:event.target.value},"تم تحديث الدور")}><option value="student">طالب</option><option value="supervisor">مشرف</option><option value="admin">إدارة</option></select><span>{data.institutions.find((item)=>item.slug===row.universitySlug)?.name||"—"}<small>{row.specialty||"—"}</small></span><span>{row.profileCompletedAt?"مكتمل":"ناقص"}<small>{row.onboardingCompletedAt?"أنهى الإرشادات":"لم يُنه الجولة"}</small></span><em className={`status ${row.status==="active"?"published":"draft"}`}>{statusLabel(row.status)}</em><span className="live-actions"><button onClick={()=>void mutate({action:"updateUser",id:row.id,role:row.role,status:row.status==="active"?"suspended":"active"},row.status==="active"?"تم إيقاف الحساب":"تم تفعيل الحساب")}>{row.status==="active"?"إيقاف":"تفعيل"}</button>{role==="student"&&<button onClick={()=>setDialog({kind:"access",user:row})}>منح مادة</button>}</span></div>)}</Table>{rows.length===0&&<p className="live-empty">لا توجد حسابات مطابقة.</p>}</section>}

function Orders({data,query}:{data:ConsoleData;query:string}){const rows=data.orders.filter((row)=>includesQuery(query,row.orderNumber,row.customerName,row.customerEmail,row.courseSlug,row.status));return <section className="admin-panel data-panel"><div className="admin-metrics compact"><Metric icon={CircleDollarSign} label="الإيراد المؤكد" value={`${data.metrics.revenue.toLocaleString("ar-SA")} ر.س`} copy="من حالات paid فقط" color="blue"/><Metric icon={CreditCard} label="المدفوع" value={String(data.metrics.paidOrders)} copy={`من ${data.metrics.orders} طلب`} color="green"/></div><Table headers={["الطلب","الطالب","المادة","التاريخ","المبلغ","الحالة"]}>{rows.map((row)=><div className="live-table-row" key={row.orderNumber}><b dir="ltr">{row.orderNumber}</b><span>{row.customerName}<small>{row.customerEmail}</small></span><span>{data.courses.find((course)=>course.slug===row.courseSlug)?.title||row.courseSlug}</span><span>{new Date(row.createdAt).toLocaleDateString("ar-SA")}</span><strong>{row.total} {row.currency}</strong><em className={`status ${row.status==="paid"?"published":"draft"}`}>{statusLabel(row.status)}</em></div>)}</Table></section>}

function Requests({data,query,mutate}:{data:ConsoleData;query:string;mutate:(p:Record<string,unknown>,s?:string)=>Promise<boolean>}){const rows=data.requests.filter((row)=>includesQuery(query,row.courseName,row.university,row.specialty,row.name,row.phone));return <section className="admin-panel data-panel"><Table headers={["المادة","الطالب","الجامعة والتخصص","المرفقات","التاريخ","الحالة"]}>{rows.map((row)=><div className="live-table-row" key={row.id}><strong>{row.courseName}<small>#{row.id}</small></strong><span>{row.name}<small>{row.phone}</small></span><span>{row.university}<small>{row.specialty}</small></span><span>{row.attachmentsCount}</span><span>{new Date(row.createdAt).toLocaleDateString("ar-SA")}</span><select value={row.status} onChange={(event)=>void mutate({action:"updateRequest",id:row.id,status:event.target.value},"تم تحديث الطلب")}><option value="new">جديد</option><option value="assigned">مسند</option><option value="reviewing">مراجعة</option><option value="planned">مخطط</option><option value="producing">إنتاج</option><option value="available">متاح</option><option value="declined">متعذر</option></select></div>)}</Table></section>}

function Support({data,query,mutate}:{data:ConsoleData;query:string;mutate:(p:Record<string,unknown>,s?:string)=>Promise<boolean>}){const rows=data.tickets.filter((row)=>includesQuery(query,row.ticketNumber,row.title,row.message,row.userEmail,row.category));return <div className="live-ticket-grid">{rows.map((row)=><article className="admin-panel live-ticket" key={row.id}><header><span><strong>{row.title}</strong><small dir="ltr">{row.ticketNumber} · {row.userEmail||"—"} · {row.contactChannel||"in_app"}</small></span><em>{statusLabel(row.status)}</em></header><div className="admin-thread"><div className="admin-thread-bubble student"><strong>الطالب</strong><p>{row.message}</p><small>{new Date(row.createdAt).toLocaleString("ar-SA")}</small></div>{row.replies.filter((reply)=>!reply.internal&&(reply.body||reply.files?.length)).map((reply)=><div className={`admin-thread-bubble ${reply.authorRole==="student"?"student":"agent"}`} key={reply.id}><strong>{reply.authorRole==="student"?"الطالب":"فريق مراس"}</strong>{reply.body&&<p>{reply.body}</p>}{reply.files?.length?<div className="support-attachments">{reply.files.map((file)=><a key={file.id} href={`/api/support/files/${file.id}`} target="_blank" rel="noreferrer"><Paperclip size={13}/>{file.originalName}</a>)}</div>:null}<small>{new Date(reply.createdAt).toLocaleString("ar-SA")}</small></div>)}</div><form className="admin-ticket-reply" onSubmit={async(event)=>{event.preventDefault();const form=new FormData(event.currentTarget);const reply=String(form.get("reply")||"");const file=form.get("file");let ok=false;if(file instanceof File&&file.size){const upload=new FormData();upload.set("ticketId",String(row.id));upload.set("message",reply);upload.set("files",file);const response=await fetch("/api/support",{method:"POST",credentials:"same-origin",body:upload});ok=response.ok;if(!ok){const result=await response.json() as {error?:string};window.alert(result.error||"تعذر إرسال الرسالة");}}else ok=await mutate({action:"updateTicket",id:row.id,status:form.get("status"),reply},"تم تحديث المحادثة");if(ok){if(file instanceof File&&file.size&&String(form.get("status"))!==row.status)await mutate({action:"updateTicket",id:row.id,status:form.get("status"),reply:""},"تم تحديث المحادثة");event.currentTarget.reset();}}}><select name="status" defaultValue={row.status}><option value="open">مفتوحة</option><option value="waiting">بانتظار الطالب</option><option value="resolved">محلولة</option><option value="closed">مغلقة</option></select><textarea name="reply" placeholder="اكتب ردًا للطالب..."/><label className="live-file"><Paperclip size={16}/><span>إرفاق ملف</span><input name="file" type="file" accept="image/*,.pdf,.doc,.docx,.ppt,.pptx,.txt"/></label><button className="button button-soft">إرسال وتحديث</button></form></article>)}</div>}

function Reviews({data,query,mutate}:{data:ConsoleData;query:string;mutate:(p:Record<string,unknown>,s?:string)=>Promise<boolean>}){const rows=data.reviews.filter((row)=>includesQuery(query,row.userEmail,row.courseSlug,row.body,row.status));return <section className="admin-panel data-panel"><div className="live-panel-note"><Star size={17}/><p>لا توجد تقييمات مزيفة جاهزة. تظهر هنا آراء طلاب لديهم شراء وتقدم مشاهدة فقط، ثم تنشر بعد المراجعة.</p></div><Table headers={["الطالب","المادة","التقييم","الرأي","الحالة","إجراء"]}>{rows.map((row)=><div className="live-table-row" key={row.id}><span>{row.userEmail}</span><span>{data.courses.find((course)=>course.slug===row.courseSlug)?.title||row.courseSlug}</span><strong className="live-stars">{"★".repeat(row.rating)}</strong><p>{row.body}</p><em>{statusLabel(row.status)}</em><select value={row.status} onChange={(event)=>void mutate({action:"updateReview",id:row.id,status:event.target.value},"تمت مراجعة التقييم")}><option value="pending">معلق</option><option value="published">نشر</option><option value="rejected">رفض</option></select></div>)}</Table></section>}

function Notifications({data,mutate}:{data:ConsoleData;mutate:(p:Record<string,unknown>,s?:string)=>Promise<boolean>}){return <div className="live-form-layout"><form className="admin-panel live-admin-form" onSubmit={async(event)=>{event.preventDefault();const form=new FormData(event.currentTarget);const ok=await mutate({action:"createNotification",audience:form.get("audience"),userEmail:form.get("userEmail"),title:form.get("title"),body:form.get("body"),actionUrl:form.get("actionUrl"),actionLabel:form.get("actionLabel"),presentation:form.get("presentation"),pushEnabled:form.get("pushEnabled")==="on",startsAt:form.get("startsAt"),expiresAt:form.get("expiresAt"),dismissible:form.get("dismissible")==="on"},"تم نشر الإشعار");if(ok)event.currentTarget.reset();}}><h2>إنشاء إعلان وإشعار</h2><p className="live-form-help">اختر مكان ظهور الإعلان، ويمكن جدولة ظهوره وإضافة زر داخلي آمن.</p><label>الجمهور<select name="audience"><option value="student">جميع الطلاب</option><option value="public">كل الزوار والطلاب</option><option value="supervisor">المشرفون</option><option value="admin">الإدارة</option></select></label><label>بريد محدد (اختياري)<input name="userEmail" type="email" dir="ltr"/></label><label>العنوان<input name="title" required/></label><label>النص<textarea name="body" required/></label><label>طريقة العرض<select name="presentation"><option value="inbox">مركز الإشعارات</option><option value="banner">شريط أعلى المنصة</option><option value="modal">نافذة عند الدخول</option><option value="all">كل القنوات</option></select></label><label>الرابط الداخلي (اختياري)<input name="actionUrl" placeholder="/courses أو /requests" dir="ltr"/></label><label>نص الزر<input name="actionLabel" placeholder="فتح التفاصيل" maxLength={80}/></label><div className="two-fields"><label>يبدأ في<input name="startsAt" type="datetime-local"/></label><label>ينتهي في<input name="expiresAt" type="datetime-local"/></label></div><label className="live-check"><input name="pushEnabled" type="checkbox" defaultChecked/> إرسال Push للأجهزة المسجلة</label><label className="live-check"><input name="dismissible" type="checkbox" defaultChecked/> السماح بإخفاء الإعلان</label><button className="button button-primary">نشر الإعلان</button></form><section className="admin-panel live-list"><h2>آخر الإشعارات</h2>{data.notifications.slice(0,30).map((row)=><article key={row.id}><Bell size={17}/><span><strong>{row.title}</strong><small>{row.presentation||"inbox"} · {row.audience} · {row.userEmail||"عام"}{row.pushEnabled===false?" · بلا Push":" · Push"}</small><p>{row.body}</p>{row.actionUrl&&<Link href={row.actionUrl}>{row.actionLabel||"فتح الرابط"}</Link>}</span></article>)}</section></div>}

function Coupons({data,mutate}:{data:ConsoleData;mutate:(p:Record<string,unknown>,s?:string)=>Promise<boolean>}){return <div className="live-form-layout"><form className="admin-panel live-admin-form" onSubmit={async(event)=>{event.preventDefault();const form=Object.fromEntries(new FormData(event.currentTarget));const ok=await mutate({action:"saveCoupon",...form},"تم حفظ الكوبون");if(ok)event.currentTarget.reset();}}><h2>إنشاء/تحديث كوبون</h2><label>الكود<input name="code" required dir="ltr"/></label><div className="two-fields"><label>النوع<select name="type"><option value="percent">نسبة %</option><option value="fixed">مبلغ ثابت</option></select></label><label>القيمة<input name="value" type="number" min="1" required/></label></div><label>مادة محددة (اختياري)<select name="courseSlug"><option value="">كل المواد</option>{data.courses.map((course)=><option value={course.slug} key={course.slug}>{course.title}</option>)}</select></label><label>حد الاستخدام<input name="usageLimit" type="number" min="1"/></label><label>تاريخ الانتهاء<input name="expiresAt" type="datetime-local"/></label><button className="button button-primary">حفظ الكوبون</button></form><section className="admin-panel live-list"><h2>الكوبونات</h2>{data.coupons.map((row)=><article key={row.id}><TicketPercent size={18}/><span><strong dir="ltr">{row.code}</strong><small>{row.type==="percent"?`${row.value}%`:`${row.value} ر.س`} · استُخدم {row.usedCount}{row.usageLimit?`/${row.usageLimit}`:""}</small></span><em>{statusLabel(row.status)}</em></article>)}</section></div>}

function Staff({data,query,mutate}:{data:ConsoleData;query:string;mutate:(p:Record<string,unknown>,s?:string)=>Promise<boolean>}){const staff=data.users.filter((row)=>row.role!=="student").filter((row)=>includesQuery(query,row.fullName,row.email,row.phone,row.role));const supervisors=data.users.filter((row)=>row.role==="supervisor");return <div className="live-form-layout"><section className="admin-panel data-panel"><div className="live-panel-note"><UserCog size={17}/><p>الحسابات الإدارية والمشرفون مرتبطون بالطلاب والكتالوج من الخادم. غيّر الدور أو الحالة من الجدول، ثم اربط المشرف بنطاق جامعة وتخصص محدد.</p></div><Table headers={["الموظف","الدور","النطاق الدراسي","الحالة","آخر دخول"]}>{staff.map((row)=><div className="live-table-row" key={row.id}><span className="live-entity"><i>{row.fullName[0]}</i><b>{row.fullName}<small>{row.email} · {row.phone||"بدون جوال"}</small></b></span><select value={row.role} onChange={(event)=>void mutate({action:"updateUser",id:row.id,status:row.status,role:event.target.value},"تم تحديث الدور")}><option value="supervisor">مشرف</option><option value="admin">إدارة</option></select><span>{data.institutions.find((item)=>item.slug===row.universitySlug)?.name||"كل الجهات"}<small>{row.specialty||"كل التخصصات"}</small></span><span className={`status ${row.status==="active"?"published":"draft"}`}>{statusLabel(row.status)}</span><span>{row.lastLoginAt?new Date(row.lastLoginAt).toLocaleDateString("ar-SA"):"لم يسجل دخولًا"}</span></div>)}</Table>{staff.length===0&&<p className="live-empty">لا توجد حسابات إدارة أو إشراف مطابقة.</p>}</section><section className="admin-panel live-admin-form"><h2>ربط مشرف بنطاق</h2><p className="live-hint">يظهر للمشرف فقط ما يطابق هذا النطاق، وتتحقق قاعدة البيانات من الجامعة والتخصص قبل الحفظ.</p><form onSubmit={async(event)=>{event.preventDefault();const form=new FormData(event.currentTarget);const ok=await mutate({action:"saveSupervisorAssignment",supervisorId:Number(form.get("supervisorId")),institutionSlug:form.get("institutionSlug"),specialty:form.get("specialty"),active:true},"تم ربط نطاق المشرف");if(ok)event.currentTarget.reset();}}><label>المشرف<select name="supervisorId" required><option value="">اختر مشرفًا</option>{supervisors.map((row)=><option value={row.id} key={row.id}>{row.fullName} — {row.email}</option>)}</select></label><label>الجامعة<select name="institutionSlug" required><option value="">اختر الجامعة</option>{data.institutions.map((row)=><option value={row.slug} key={row.slug}>{row.name}</option>)}</select></label><label>التخصص<select name="specialty" required><option value="">اختر التخصص</option>{data.specialties.map((row)=><option value={row.name} key={row.slug}>{row.name}</option>)}</select></label><button className="button button-primary" disabled={!supervisors.length}><Plus size={15}/> حفظ الربط</button></form><h2 className="staff-assignment-title">النطاقات الحالية</h2><div className="staff-assignment-list">{data.supervisorAssignments.map((assignment)=><article key={assignment.id}><span><strong>{supervisors.find((row)=>row.id===assignment.supervisorId)?.fullName||`مشرف #${assignment.supervisorId}`}</strong><small>{data.institutions.find((row)=>row.slug===assignment.institutionSlug)?.name||assignment.institutionSlug} · {assignment.specialty}</small></span><button className={`status ${assignment.active?"published":"draft"}`} onClick={()=>void mutate({action:"saveSupervisorAssignment",id:assignment.id,supervisorId:assignment.supervisorId,institutionSlug:assignment.institutionSlug,specialty:assignment.specialty,active:!assignment.active},assignment.active?"تم إيقاف نطاق المشرف":"تم تفعيل نطاق المشرف")}>{assignment.active?"نشط":"موقوف"}</button></article>)}</div>{!data.supervisorAssignments.length&&<p className="live-empty">لا توجد نطاقات إشراف بعد.</p>}</section></div>}

const settingFields:ReadonlyArray<{key:string;label:string;type?:"email";dir?:"ltr"}>=[{key:"support_email",label:"بريد الدعم",type:"email"},{key:"support_hours",label:"ساعات الدعم"},{key:"whatsapp_number",label:"رقم واتساب",dir:"ltr"},{key:"whatsapp_message",label:"رسالة واتساب الافتراضية"},{key:"social_x",label:"رابط X",dir:"ltr"},{key:"social_instagram",label:"رابط Instagram",dir:"ltr"},{key:"social_tiktok",label:"رابط TikTok",dir:"ltr"},{key:"social_youtube",label:"رابط YouTube",dir:"ltr"},{key:"social_telegram",label:"رابط Telegram",dir:"ltr"},{key:"social_linkedin",label:"رابط LinkedIn",dir:"ltr"},{key:"social_facebook",label:"رابط Facebook",dir:"ltr"},{key:"social_snapchat",label:"رابط Snapchat",dir:"ltr"},{key:"social_threads",label:"رابط Threads",dir:"ltr"}];
function PlatformSettings({data,mutate}:{data:ConsoleData;mutate:(p:Record<string,unknown>,s?:string)=>Promise<boolean>}){return <form className="admin-panel live-settings" onSubmit={async(event)=>{event.preventDefault();await mutate({action:"saveSettings",values:Object.fromEntries(new FormData(event.currentTarget))},"تم تحديث التواصل والمساعد والواجهة");}}><div className="live-panel-note"><MessageSquareText size={18}/><p>هذه القيم تظهر تلقائيًا في التذييل وصفحات الدعم والمساعد الذكي. الروابط الخارجية تقبل HTTPS فقط.</p></div><div>{settingFields.map((field)=><label key={field.key}>{field.label}<input name={field.key} type={field.type||"text"} defaultValue={data.settings[field.key]||""} dir={field.dir}/></label>)}</div><label>تنبيه عام<textarea name="announcement" defaultValue={data.settings.announcement||""} maxLength={500}/></label><button className="button button-primary">حفظ جميع الإعدادات</button></form>}

function Audit({data,query}:{data:ConsoleData;query:string}){const rows=data.audit.filter((row)=>includesQuery(query,row.actorEmail,row.action,row.entityType,row.entityId));return <section className="admin-panel data-panel"><Table headers={["الوقت","المنفذ","العملية","نوع السجل","المعرّف"]}>{rows.map((row)=><div className="live-table-row" key={row.id}><span>{new Date(row.createdAt).toLocaleString("ar-SA")}</span><strong>{row.actorEmail}</strong><span>{row.action}</span><span>{row.entityType}</span><span dir="ltr">{row.entityId||"—"}</span></div>)}</Table></section>}

function AdminDialog({dialog,data,close,mutate,refresh}:{dialog:Exclude<Dialog,null>;data:ConsoleData;close:()=>void;mutate:(p:Record<string,unknown>,s?:string)=>Promise<boolean>;refresh:()=>Promise<void>}){const[busy,setBusy]=useState(false);const[error,setError]=useState("");const submit=async(event:React.FormEvent<HTMLFormElement>)=>{event.preventDefault();setBusy(true);setError("");const form=new FormData(event.currentTarget);try{if(dialog.kind==="institution"){if(!await mutate({action:"saveInstitution",slug:form.get("slug"),name:form.get("name"),nameEn:form.get("nameEn"),region:form.get("region"),type:form.get("type"),domain:form.get("domain"),directorySourceUrl:form.get("directorySourceUrl"),verificationStatus:form.get("verificationStatus"),aliases:String(form.get("aliases")||"").split("\n").map((value)=>value.trim()).filter(Boolean),logoUrl:form.get("logoUrl"),status:form.get("status"),featured:form.get("featured")==="on"}))throw new Error("تعذر حفظ بيانات الجهة");const file=form.get("logoFile");if(file instanceof File&&file.size){const upload=new FormData();upload.set("slug",String(form.get("slug")));upload.set("file",file);const response=await fetch("/api/admin/logos",{method:"POST",credentials:"same-origin",body:upload});const result=await response.json() as {error?:string};if(!response.ok)throw new Error(result.error||"تعذر رفع الشعار");await refresh();}}else if(dialog.kind==="specialty"){if(!await mutate({action:"saveSpecialty",slug:form.get("slug"),name:form.get("name"),description:form.get("description"),sourceUrl:form.get("sourceUrl"),verifiedAt:form.get("verifiedAt"),verificationStatus:form.get("verificationStatus"),faculty:form.get("faculty"),degree:form.get("degree"),status:form.get("status"),institutionSlug:form.get("institutionSlug")}))throw new Error("تعذر حفظ التخصص");}else if(dialog.kind==="course"){if(!await mutate({action:"saveCourse",slug:form.get("slug"),title:form.get("title"),titleEn:form.get("titleEn"),code:form.get("code"),description:form.get("description"),institutionSlug:form.get("institutionSlug"),specialtySlug:form.get("specialtySlug"),price:Number(form.get("price")),oldPrice:Number(form.get("oldPrice")),accessLabel:form.get("accessLabel"),sourceUrl:form.get("sourceUrl"),verifiedAt:form.get("verifiedAt"),status:form.get("status"),featured:form.get("featured")==="on",coverTheme:form.get("coverTheme")}))throw new Error("تعذر حفظ المادة");}else if(dialog.kind==="staff"){const response=await fetch("/api/admin/staff",{method:"POST",credentials:"same-origin",headers:{"content-type":"application/json"},body:JSON.stringify({email:form.get("email"),fullName:form.get("fullName"),phone:form.get("phone"),password:form.get("password"),role:form.get("role"),universitySlug:form.get("universitySlug"),specialty:form.get("specialty")})});const result=await response.json() as {error?:string};if(!response.ok)throw new Error(result.error||"تعذر حفظ الموظف");await refresh();}else if(dialog.kind==="access"){if(!await mutate({action:"grantAccess",userEmail:dialog.user.email,courseSlug:form.get("courseSlug"),expiresAt:form.get("expiresAt")},"تم منح صلاحية المادة"))throw new Error("تعذر منح صلاحية المادة");}close();}catch(caught){setError(caught instanceof Error?caught.message:"تعذر الحفظ");setBusy(false);}};const item=dialog.kind==="institution"?dialog.item:dialog.kind==="specialty"?dialog.item:dialog.kind==="course"?dialog.item:undefined;return <div className="admin-modal-overlay"><button onClick={close} aria-label="إغلاق"/><form className="admin-modal live-modal" onSubmit={submit}><div><span><Settings size={19}/></span><div><h2>{dialog.kind==="access"?`منح مادة إلى ${dialog.user.fullName}`:item?"تعديل السجل":"إضافة سجل جديد"}</h2><p>يحفظ التغيير في قاعدة البيانات ويسجل في سجل النشاط.</p></div><button type="button" onClick={close}><X size={19}/></button></div>{dialog.kind==="institution"&&<><label>المعرّف<input name="slug" required readOnly={Boolean(dialog.item)} defaultValue={dialog.item?.slug} pattern="[A-Za-z0-9._-]{2,80}" dir="ltr"/></label><label>الاسم العربي<input name="name" required defaultValue={dialog.item?.name}/></label><label>الاسم الإنجليزي<input name="nameEn" defaultValue={dialog.item?.nameEn} dir="ltr"/></label><div className="two-fields"><label>المنطقة<input name="region" required defaultValue={dialog.item?.region}/></label><label>النوع<select name="type" defaultValue={dialog.item?.type||"حكومية"}><option>حكومية</option><option>أهلية</option><option>كلية</option><option>تقنية</option></select></label></div><label>النطاق الرسمي<input name="domain" defaultValue={dialog.item?.domain} placeholder="university.edu.sa" dir="ltr"/></label><label>رابط دليل الجهة HTTPS<input name="directorySourceUrl" defaultValue={dialog.item?.directorySourceUrl} placeholder="https://..." dir="ltr"/></label><label>الأسماء البديلة (كل اسم في سطر)<textarea name="aliases" defaultValue={(dialog.item?.aliases||[]).join("\n")} /></label><div className="two-fields"><label>حالة التحقق<select name="verificationStatus" defaultValue={dialog.item?.verificationStatus||"official-directory"}><option value="official-directory">دليل رسمي</option><option value="pending-review">قيد المراجعة</option></select></label><span /></div><label>رابط شعار HTTPS<input name="logoUrl" defaultValue={dialog.item?.logo?.startsWith("http")?dialog.item.logo:""} dir="ltr"/></label><label className="live-file"><Upload size={18}/><span>أو ارفع ملف شعار شفاف</span><input name="logoFile" type="file" accept="image/png,image/jpeg,image/webp"/></label><label>الحالة<select name="status" defaultValue={dialog.item?.status||"published"}><option value="published">منشور</option><option value="hidden">مخفي</option></select></label><label className="live-check"><input name="featured" type="checkbox" defaultChecked={dialog.item?.featured}/> إظهار في الصفحة الرئيسية</label></>}{dialog.kind==="specialty"&&<><label>المعرّف<input name="slug" required readOnly={Boolean(dialog.item)} defaultValue={dialog.item?.slug} pattern="[A-Za-z0-9._-]{2,80}" dir="ltr"/></label><label>اسم التخصص<input name="name" required defaultValue={dialog.item?.name}/></label><label>الوصف<textarea name="description" defaultValue={dialog.item?.description}/></label><label>رابط المصدر الرسمي<input name="sourceUrl" defaultValue={dialog.item?.sourceUrl} dir="ltr" placeholder="https://..."/></label><div className="two-fields"><label>الكلية/القسم<input name="faculty" defaultValue={dialog.item?.faculty||""}/></label><label>الدرجة<input name="degree" defaultValue={dialog.item?.degree||""}/></label></div><label>تاريخ التحقق<input name="verifiedAt" defaultValue={dialog.item?.verifiedAt||""} dir="ltr" placeholder="2026-08-27"/></label><div className="two-fields"><label>حالة التحقق<select name="verificationStatus" defaultValue={dialog.item?.verificationStatus||"pending-review"}><option value="official-program">برنامج رسمي</option><option value="pending-review">قيد المراجعة</option><option value="discovery">اكتشافي</option></select></label><span /></div><label>ربطه بجهة<select name="institutionSlug"><option value="">بدون ربط جديد</option>{data.institutions.map((row)=><option value={row.slug} key={row.slug}>{row.name}</option>)}</select></label><label>الحالة<select name="status" defaultValue={dialog.item?.status||"published"}><option value="published">منشور</option><option value="hidden">مخفي</option></select></label></>}{dialog.kind==="course"&&<><label>المعرّف<input name="slug" required readOnly={Boolean(dialog.item)} defaultValue={dialog.item?.slug} pattern="[A-Za-z0-9._-]{2,80}" dir="ltr"/></label><label>العنوان<input name="title" required defaultValue={dialog.item?.title}/></label><div className="two-fields"><label>العنوان الإنجليزي<input name="titleEn" defaultValue={dialog.item?.titleEn} dir="ltr"/></label><label>رمز المادة<input name="code" defaultValue={dialog.item?.code} dir="ltr"/></label></div><label>الوصف<textarea name="description" defaultValue={dialog.item?.description||"شرح جامعي منظم مع درس تجريبي قبل الاشتراك."}/></label><label>الجامعة<select name="institutionSlug" required defaultValue={dialog.item?.universitySlug}><option value="">اختر</option>{data.institutions.map((row)=><option value={row.slug} key={row.slug}>{row.name}</option>)}</select></label><label>التخصص الإداري<select name="specialtySlug" required defaultValue={dialog.item?.specialtySlug||""}><option value="">اختر تخصصًا أضفته في الإدارة</option>{data.specialties.map((row)=><option value={row.slug} key={row.slug}>{row.name}</option>)}</select></label><div className="two-fields"><label>السعر<input name="price" type="number" min="0" required defaultValue={dialog.item?.price||0}/></label><label>السعر السابق<input name="oldPrice" type="number" min="0" defaultValue={dialog.item?.oldPrice}/></label></div><label>مدة الوصول<input name="accessLabel" defaultValue={dialog.item?.access||"90 يومًا"}/></label><label>رابط الخطة/المصدر الرسمي<input name="sourceUrl" defaultValue={dialog.item?.sourceUrl||""} dir="ltr" placeholder="https://..."/></label><label>تاريخ التحقق<input name="verifiedAt" defaultValue={dialog.item?.verifiedAt||""} dir="ltr" placeholder="2026-08-27"/></label><div className="two-fields"><label>الحالة<select name="status" defaultValue={dialog.item?.status||"draft"}><option value="draft">مسودة</option><option value="published">منشور</option><option value="hidden">مخفي</option></select></label><label>النمط<select name="coverTheme" defaultValue={dialog.item?.coverTheme||"blue-violet"}><option value="blue-violet">أزرق بنفسجي</option><option value="emerald-blue">زمردي أزرق</option><option value="orange-red">برتقالي أحمر</option><option value="indigo-cyan">نيلي سماوي</option></select></label></div><label className="live-check"><input name="featured" type="checkbox" defaultChecked={dialog.item?.featured}/> مادة مميزة</label></>}{dialog.kind==="staff"&&<><label>البريد الإلكتروني<input name="email" type="email" required dir="ltr"/></label><label>الاسم الكامل<input name="fullName" required minLength={5}/></label><label>الجوال السعودي<input name="phone" required placeholder="05xxxxxxxx" dir="ltr"/></label><label>كلمة المرور المؤقتة<input name="password" type="password" required minLength={10} autoComplete="new-password"/></label><div className="two-fields"><label>الدور<select name="role" defaultValue="supervisor"><option value="supervisor">مشرف</option><option value="admin">مدير إدارة</option></select></label><label>الجامعة<select name="universitySlug" required><option value="">اختر الجامعة</option>{data.institutions.map((row)=><option value={row.slug} key={row.slug}>{row.name}</option>)}</select></label></div><label>التخصص<select name="specialty" required><option value="">اختر التخصص</option>{data.specialties.map((row)=><option value={row.name} key={row.slug}>{row.name}</option>)}</select></label></>}{dialog.kind==="access"&&<><label>المادة<select name="courseSlug" required><option value="">اختر</option>{data.courses.map((course)=><option value={course.slug} key={course.slug}>{course.title} — {course.university}</option>)}</select></label><label>انتهاء الصلاحية (اختياري)<input name="expiresAt" type="datetime-local"/></label></>}{error&&<p className="form-error">{error}</p>}<footer><button type="button" className="button button-ghost" onClick={close}>إلغاء</button><button className="button button-primary" disabled={busy}>{busy?"جارٍ الحفظ...":"حفظ"}</button></footer></form></div>}
